UPDATE pf.workspace_environment SET operation_id=#{operationId},fence=#{fence},version=version+1,updated_at=clock_timestamp()
        WHERE id=#{previous.environmentId} AND space_id=#{previous.spaceId} AND workspace_id=#{previous.workspaceId} AND generation=#{previous.generation} AND fence=#{currentFence}
        AND operation_id=#{previous.operationId} AND state='READY'
